import{c as a,S as o,j as r,m as t}from"./chunks/framework.DjygN48H.js";const m=JSON.parse('{"title":"Conductor","description":"","frontmatter":{},"headers":[],"relativePath":"developer/architecture/conductor.md","filePath":"developer/architecture/conductor.md"}'),n={name:"developer/architecture/conductor.md"};function s(d,e,c,i,l,u){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="conductor" tabindex="-1">Conductor <a class="header-anchor" href="#conductor" aria-label="Permalink to “Conductor”">​</a></h1><p><a href="https://github.com/source-academy/conductor" target="_blank" rel="noreferrer"><code>conductor</code></a> is the standard communication interface for languages: the one way in which a host and an evaluator talk, whatever the language. Checked against the repository&#39;s README on 28 November 2026.</p><h2 id="terms" tabindex="-1">Terms <a class="header-anchor" href="#terms" aria-label="Permalink to “Terms”">​</a></h2><ul><li><strong>Host</strong>: an environment from which runners are created, such as the browser frontend, a command line, or the <a href="./grader">grader</a>.</li><li><strong>Runner</strong>: an environment where user code runs.</li><li><strong>Evaluator</strong>: a program that processes user code and produces the results.</li><li><strong>Channel</strong>: a named, bidirectional data stream between a host and a runner.</li><li><strong>Chunk</strong>: a piece of user code that belongs to no file (for example a line typed in the REPL).</li><li><strong>Plugin</strong>: a program loaded on demand that can receive messages and send on declared channels.</li></ul><h2 id="how-the-parts-fit" tabindex="-1">How the parts fit <a class="header-anchor" href="#how-the-parts-fit" aria-label="Permalink to “How the parts fit”">​</a></h2><p>The host creates a <code>Conduit</code> for a Web Worker (or a worker thread) and registers a host plugin; the runner&#39;s entry file creates its own <code>Conduit</code> and registers the runner plugin with the evaluator (<code>initialise(MyEvaluator)</code>). The standard channels carry results (<code>__result</code>), errors (<code>__error</code>), standard output (<code>__stdio</code>) and status (<code>__status</code>). An evaluator implements <code>IEvaluator</code>; the abstract class <code>BasicEvaluator</code> needs only <code>evaluateChunk</code>, and <code>evaluateFile</code> can be overridden. The runner asks its host for files (<code>requestFile</code>) and for plugins to be loaded (<code>hostLoadPlugin</code>); the frontend answers in <code>src/features/conductor</code>.</p><h2 id="the-module-interface" tabindex="-1">The module interface <a class="header-anchor" href="#the-module-interface" aria-label="Permalink to “The module interface”">​</a></h2><p>Modules make no assumption about an evaluator&#39;s memory model. The evaluator provides functions with which a module reads, builds and calls values: the standard data types (void, boolean, number, integer, string, empty list, pair, array, closure, opaque, list), some passed as JavaScript values and some as identifiers, and a standard library. Errors thrown by modules and evaluators use the classes in <code>conductor/common</code> (such as <code>EvaluatorRuntimeError</code> and <code>EvaluatorSyntaxError</code>), so that hosts can recognise and show them.</p><h2 id="using-it" tabindex="-1">Using it <a class="header-anchor" href="#using-it" aria-label="Permalink to “Using it”">​</a></h2><p>The frontend depends on Conductor as the npm package <code>@sourceacademy/conductor</code> (version <code>^0.8.3</code> on 28 November 2026; the repository&#39;s README still says to load it from GitHub, which is out of date). To run an evaluator in the frontend, deploy it so that it appears in the <a href="./directories">language directory</a>, or use the <code>conductor.evaluator.url</code> feature flag for one under development. The repository has a template, <code>conductor-runner-example</code>, for a new evaluator.</p>',10)])])}const p=a(n,[["render",s]]);export{m as __pageData,p as default};
